, "sort_order": 1, "text_md5": "6bcc85be806398593d6fd02f163cb699", "notes_md5": "c91bfd9f8a361908578e28041c9db5f0"}, {"id": "91fde768-6815-5be4-804d-e0f3d73be3de", "research_id": "d3254254-c82c-5732-9ed1-dd66270b8a20", "item_key": "digital_maturity", "priority": 2, "sort_order": 2, "text_md5": "e8fa584f4843e4e47f53878a7e574708", "notes_md5": "c91bfd9f8a361908578e28041c9db5f0"}, {"id": "85b09c2f-ec3d-5ab5-a639-e78ce2170174", "research_id": "d3254254-c82c-5732-9ed1-dd66270b8a20", "item_key": "communication_opportunity", "priority": 2, "sort_order": 3, "text_md5": "de2c565d5c0c1832a5973f72362190e9", "notes_md5": "c91bfd9f8a361908578e28041c9db5f0"}, {"id": "fef7e990-0eae-57b7-9039-5bca72c967ac", "research_id": "d3254254-c82c-5732-9ed1-dd66270b8a20", "item_key": "evidence_limitations", "priority": 3, "sort_order": 4, "text_md5": "843a5febfed43240d9c38882e318a22b", "notes_md5": "d3db4f567c7b9d9e75372d1968ee98b1"}]$items$::jsonb)
 as x(id uuid,research_id uuid,item_key text,priority integer,sort_order integer,text_md5 text,notes_md5 text)
)
select
 (select count(*) from expected_taxons) as expected_new_taxons,
 (select count(*) from expected_research) as expected_research_parents,
 (select count(*) from expected_items) as expected_research_items,
 (select count(*) from expected_taxons e left join public.business_taxons t on t.id=e.id
   left join public.business_taxons parent on parent.id=t.parent_id
   where t.id is null or t.slug<>e.slug or t.name<>e.name or t.level<>e.level or not t.is_active
     or parent.slug is distinct from e.parent_slug
     or (e.level='niche' and (parent.level<>'segment' or not parent.is_active))
 ) as invalid_taxons,
 (select count(*) from expected_research e left join public.taxon_market_research r on r.id=e.id
   left join public.business_taxons t on t.id=r.taxon_id
   where r.id is null or t.slug<>e.taxon_slug or not t.is_active or t.level<>'niche'
     or r.research_block<>'market_intelligence' or r.audience_scope<>'business_buyer'
     or r.version<>1 or r.status<>'active'
     or (select count(*) from public.taxon_market_research_items i where i.research_id=r.id)<>e.items
 ) as invalid_research,
 (select count(*) from expected_items e left join public.taxon_market_research_items i on i.id=e.id
   where i.id is null or i.research_id<>e.research_id or not i.is_active or i.item_key<>e.item_key
     or i.priority<>e.priority or i.sort_order<>e.sort_order
     or md5(i.item_text)<>e.text_md5 or md5(i.notes) is distinct from e.notes_md5
 ) as invalid_items,
 (select md5(coalesce(string_agg(row_to_json(t)::text,E'\n' order by t.id),''))
   from public.business_taxons t where t.id not in (select id from expected_taxons))
   is distinct from '1d6c7429363a9ea70dfcb9f88ea278ab' as invalid_preserved_taxons,
 (select md5(coalesce(string_agg(row_to_json(r)::text,E'\n' order by r.id),''))
   from public.taxon_market_research r where r.id not in (select id from expected_research))
   is distinct from 'c1c05aaba0a652abd7a92b75c61e6882' as invalid_preserved_research,
 (select md5(coalesce(string_agg(row_to_json(i)::text,E'\n' order by i.id),''))
   from public.taxon_market_research_items i where i.id not in (select id from expected_items))
   is distinct from '279a806018c93500c7e59bfb8e234f27' as invalid_preserved_items,
 (select count(*) from public.business_taxon_aliases) as aliases_count,
 (select md5(coalesce(string_agg(row_to_json(a)::text,E'\n' order by a.id),''))
